# -*- coding: utf-8 -*-
"""ejecutar_tests.py -- corredor de la suite SIN pytest (solo libreria estandar).

Sirve para ver el estado de la suite cuando no hay pytest a mano:

    python ejecutar_tests.py

Sale 0 si la suite pasa entera y 1 si algo falla. NO TOCAR: es parte del arnes de la tarea.
"""
from __future__ import annotations

import importlib
import inspect
import os
import sys
import tempfile
import traceback
from pathlib import Path

RAIZ = os.path.dirname(os.path.abspath(__file__))
if RAIZ not in sys.path:
    sys.path.insert(0, RAIZ)

MODULOS = ["tests.test_almacen", "tests.test_precios", "tests.test_texto",
           "tests.test_arbol", "tests.test_concurrencia"]


def main():
    pasados, fallos = 0, []
    for nombre in MODULOS:
        try:
            mod = importlib.import_module(nombre)
        except Exception:
            fallos.append((nombre, traceback.format_exc()))
            continue
        for fn_nombre, fn in sorted(vars(mod).items()):
            if not fn_nombre.startswith("test_") or not callable(fn):
                continue
            firma = inspect.signature(fn)
            try:
                if "tmp_path" in firma.parameters:
                    with tempfile.TemporaryDirectory() as tmp:
                        fn(Path(tmp))
                else:
                    fn()
                pasados += 1
                print("PASS %s.%s" % (nombre, fn_nombre))
            except Exception:
                fallos.append(("%s.%s" % (nombre, fn_nombre), traceback.format_exc()))
                print("FAIL %s.%s" % (nombre, fn_nombre))
    print("\n%d pasados, %d fallos" % (pasados, len(fallos)))
    for nombre, tb in fallos:
        print("\n--- %s ---\n%s" % (nombre, tb))
    return 0 if not fallos else 1


if __name__ == "__main__":
    sys.exit(main())

