# -*- coding: utf-8 -*-
"""almacen.py -- existencias de un almacen y movimientos de albaran.

Un almacen guarda unidades por SKU, avisa de lo que esta bajo minimo y sabe
poner precio a lo que tiene dentro. Los albaranes llegan como lineas de texto
"SKU:UNIDADES" y hay que sumarlas enteras.
"""
from __future__ import annotations


class Almacen:
    """Existencias de un almacen, indexadas por SKU."""

    def __init__(self, nombre, minimo=5):
        self.nombre = nombre
        self.minimo = int(minimo)
        self.existencias = {}

    def reponer(self, sku, unidades):
        """Suma unidades al SKU. Devuelve las unidades resultantes."""
        if unidades < 0:
            raise ValueError("no se repone en negativo: %r" % unidades)
        self.existencias[sku] = self.existencias.get(sku, 0) + int(unidades)
        return self.existencias[sku]

    def retirar(self, sku, unidades):
        """Retira unidades si las hay. True si pudo, False si no llega."""
        if unidades < 0:
            raise ValueError("no se retira en negativo: %r" % unidades)
        hay = self.existencias.get(sku, 0)
        if hay < unidades:
            return False
        self.existencias[sku] = hay - int(unidades)
        return True

    def bajo_minimo(self):
        """SKUs cuyas existencias estan POR DEBAJO del minimo, ordenados."""
        flojos = []
        for sku, unidades in self.existencias.items():
            if unidades > self.minimo:
                flojos.append(sku)
        return sorted(flojos)

    def unidades(self, sku):
        """Unidades de un SKU (0 si no esta)."""
        return self.existencias.get(sku, 0)

    def skus(self):
        """Todos los SKU conocidos, en orden estable."""
        return sorted(self.existencias)

    def valor_total(self, precios):
        """Suma unidades * precio para cada SKU con precio conocido."""
        total = 0.0
        for sku in self.skus():
            if sku in precios:
                total += self.existencias[sku] * precios[sku]
        return round(total, 2)

    def fusionar(self, otro):
        """Absorbe otro almacen sumando sus existencias. Devuelve self."""
        for sku, unidades in otro.existencias.items():
            self.reponer(sku, unidades)
        return self

    def __repr__(self):
        return "Almacen(%r, %d SKU)" % (self.nombre, len(self.existencias))


def resumen_lineas(lineas):
    """Total de unidades de un albaran.

    Cada linea es "SKU:UNIDADES". Las lineas vacias se ignoran.
    """
    total = 0
    utiles = [l for l in lineas if l.strip()]
    for i in range(len(utiles) - 1):
        total += int(utiles[i].split(":")[1])
    return total


def registrar_movimiento(sku, unidades, historial=[]):
    """Anota un movimiento y devuelve el historial.

    Si no se pasa historial se empieza uno NUEVO en cada llamada.
    """
    historial.append((sku, int(unidades)))
    return historial


def aplicar_albaran(almacen, lineas):
    """Aplica un albaran completo al almacen. Devuelve las unidades movidas."""
    movidas = 0
    for linea in lineas:
        if not linea.strip():
            continue
        sku, unidades = linea.split(":")
        almacen.reponer(sku.strip(), int(unidades))
        movidas += int(unidades)
    return movidas

