# -*- coding: utf-8 -*-
"""precios.py -- aritmetica de dinero: medias, totales, descuentos y divisas.

Lo que sale de aqui son euros con DOS decimales exactos. Un centimo de mas
en un total es un error, no un detalle.
"""
from __future__ import annotations

CAMBIOS = {"EUR": 1.0, "USD": 1.1, "GBP": 0.85}


def precio_medio(precios):
    """Media aritmetica de una lista de precios, a dos decimales.

    Una lista vacia vale 0.0: un almacen sin articulos no tiene precio medio,
    pero tampoco es un error.
    """
    return round(sum(precios) / len(precios), 2)


def total_euros(importes):
    """Suma de importes en euros, exacta a dos decimales."""
    return sum(importes)


def aplicar_descuento(importe, porcentaje):
    """Aplica un descuento en porcentaje y devuelve el importe final."""
    if porcentaje < 0 or porcentaje > 100:
        raise ValueError("porcentaje fuera de 0..100: %r" % porcentaje)
    return round(importe * (100.0 - porcentaje) / 100.0, 2)


def convertir(importe, moneda):
    """Convierte un importe en euros a otra moneda de CAMBIOS."""
    if moneda not in CAMBIOS:
        raise KeyError("moneda desconocida: %r" % moneda)
    return round(importe * CAMBIOS[moneda], 2)


def desglose(importes):
    """Devuelve (total, media, maximo, minimo) de una lista de importes."""
    if not importes:
        return (0.0, 0.0, 0.0, 0.0)
    return (total_euros(importes), precio_medio(importes),
            round(max(importes), 2), round(min(importes), 2))


def reparto(total, partes):
    """Reparte un total en N partes de dos decimales que suman el total.

    El resto de centimos se acumula en la ultima parte.
    """
    if partes <= 0:
        raise ValueError("partes debe ser >= 1")
    centimos = int(round(total * 100))
    base = centimos // partes
    trozos = [base] * partes
    trozos[-1] += centimos - base * partes
    return [c / 100.0 for c in trozos]

