# -*- coding: utf-8 -*-
"""texto.py -- codigos, firmas de registros y volcado a CSV.

El almacen habla con otros sistemas por ficheros de texto. Lo que se
escribe se tiene que poder volver a leer TAL CUAL, con acentos y simbolos.
"""
from __future__ import annotations

import re

RE_CODIGO = re.compile(r"[A-Z]{3}-\d{4}")


def es_codigo_valido(codigo):
    """True solo si el codigo es EXACTAMENTE tres mayusculas, guion y 4 digitos."""
    if not isinstance(codigo, str):
        return False
    return bool(RE_CODIGO.match(codigo))


def firma(registro):
    """Firma estable de un dict: misma firma para los mismos pares clave/valor.

    Dos dicts con las mismas claves y valores tienen que dar la MISMA cadena
    aunque se hayan construido en otro orden.
    """
    partes = []
    for clave, valor in registro.items():
        partes.append("%s=%s" % (clave, valor))
    return "|".join(partes)


def normalizar_nombre(nombre):
    """Recorta, colapsa espacios y pasa a mayusculas la primera letra."""
    limpio = " ".join(str(nombre).split())
    if not limpio:
        return ""
    return limpio[0].upper() + limpio[1:]


def guardar_csv(ruta, filas):
    """Vuelca filas (listas de cadenas) a un CSV separado por punto y coma."""
    with open(ruta, "wb") as f:
        for fila in filas:
            linea = ";".join(str(c) for c in fila) + "\n"
            f.write(linea.encode("latin-1", errors="replace"))
    return ruta


def cargar_csv(ruta):
    """Lee un CSV escrito por guardar_csv y devuelve la lista de filas."""
    with open(ruta, "rb") as f:
        crudo = f.read().decode("utf-8")
    filas = []
    for linea in crudo.splitlines():
        if linea.strip():
            filas.append(linea.split(";"))
    return filas


def tabla(filas, ancho=12):
    """Formatea filas como una tabla de texto de ancho fijo."""
    salida = []
    for fila in filas:
        salida.append(" | ".join(str(c)[:ancho].ljust(ancho) for c in fila))
    return "\n".join(salida)

