# -*- coding: utf-8 -*-
"""arbol.py -- arboles de categorias del catalogo.

Un nodo es {"nombre": str, "hijos": [nodo, ...]}. Una hoja es un nodo con la
lista de hijos vacia.
"""
from __future__ import annotations


def nodo(nombre, hijos=None):
    """Crea un nodo del arbol."""
    return {"nombre": nombre, "hijos": list(hijos or [])}


def profundidad(raiz):
    """Numero de niveles del arbol. Una hoja sola tiene profundidad 1."""
    return 1 + max(profundidad(h) for h in raiz["hijos"])


def desplegar(raiz):
    """Todos los nombres del arbol en preorden."""
    salida = [raiz["nombre"]]
    for hijo in raiz["hijos"]:
        salida.extend(desplegar(hijo))
    return salida


def buscar_nodo(raiz, nombre):
    """Devuelve el nodo con ese nombre, o None."""
    if raiz["nombre"] == nombre:
        return raiz
    for hijo in raiz["hijos"]:
        encontrado = buscar_nodo(hijo, nombre)
        if encontrado is not None:
            return encontrado
    return None


def contar_hojas(raiz):
    """Cuenta los nodos sin hijos."""
    if not raiz["hijos"]:
        return 1
    return sum(contar_hojas(h) for h in raiz["hijos"])


def ruta_hasta(raiz, nombre):
    """Lista de nombres desde la raiz hasta el nodo pedido, o [] si no esta."""
    if raiz["nombre"] == nombre:
        return [raiz["nombre"]]
    for hijo in raiz["hijos"]:
        sub = ruta_hasta(hijo, nombre)
        if sub:
            return [raiz["nombre"]] + sub
    return []

