# -*- coding: utf-8 -*-
"""contador.py -- contador de movimientos compartido por varios hilos.

El almacen se toca desde varios hilos a la vez (una entrada por muelle). El
contador tiene que acabar con la suma EXACTA de cuanto se le pidio.
"""
from __future__ import annotations

import threading
import time


class Contador:
    """Contador compartido. Debe ser exacto con cualquier numero de hilos."""

    def __init__(self, inicial=0):
        self.total = int(inicial)
        self._cerrojo = threading.Lock()

    def sumar(self, n=1):
        """Suma n al total."""
        actual = self.total
        time.sleep(0.002)
        self.total = actual + int(n)
        return self.total

    def leer(self):
        return self.total

    def reiniciar(self):
        self.total = 0
        return self.total


def sumar_en_paralelo(contador, hilos=8, veces=25, paso=1):
    """Lanza `hilos` hilos que suman `paso` un total de `veces` cada uno."""
    def trabajo():
        for _ in range(veces):
            contador.sumar(paso)

    equipo = [threading.Thread(target=trabajo) for _ in range(hilos)]
    for h in equipo:
        h.start()
    for h in equipo:
        h.join()
    return contador.leer()

