# -*- coding: utf-8 -*-
"""Tests de la aritmetica de dinero."""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from inventario.precios import (aplicar_descuento, convertir, desglose,
                                precio_medio, reparto, total_euros)


def test_precio_medio_normal():
    assert precio_medio([2.0, 4.0]) == 3.0
    assert precio_medio([1.0, 2.0, 4.0]) == 2.33


def test_precio_medio_de_lista_vacia_vale_cero():
    assert precio_medio([]) == 0.0


def test_total_euros_exacto_a_dos_decimales():
    assert total_euros([0.1, 0.2, 0.3]) == 0.6
    assert total_euros([1.1, 2.2]) == 3.3
    assert total_euros([]) == 0.0


def test_aplicar_descuento():
    assert aplicar_descuento(100.0, 10) == 90.0
    assert aplicar_descuento(20.0, 50) == 10.0
    assert aplicar_descuento(19.99, 0) == 19.99


def test_descuento_fuera_de_rango():
    for malo in (-1, 101):
        try:
            aplicar_descuento(10.0, malo)
        except ValueError:
            continue
        raise AssertionError("deberia haber lanzado ValueError con %r" % malo)


def test_convertir():
    assert convertir(10.0, "EUR") == 10.0
    assert convertir(10.0, "USD") == 11.0


def test_desglose_de_lista_vacia():
    assert desglose([]) == (0.0, 0.0, 0.0, 0.0)


def test_desglose_normal():
    assert desglose([0.1, 0.2, 0.3]) == (0.6, 0.2, 0.3, 0.1)


def test_reparto_suma_el_total():
    trozos = reparto(10.0, 3)
    assert len(trozos) == 3
    assert round(sum(trozos), 2) == 10.0

