# -*- coding: utf-8 -*-
"""Tests del arbol de categorias."""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from inventario.arbol import (buscar_nodo, contar_hojas, desplegar, nodo,
                              profundidad, ruta_hasta)


def arbolito():
    return nodo("raiz", [nodo("a", [nodo("a1"), nodo("a2")]), nodo("b")])


def test_profundidad_de_una_hoja_sola():
    assert profundidad(nodo("solo")) == 1


def test_profundidad_de_un_arbol():
    assert profundidad(arbolito()) == 3


def test_desplegar_en_preorden():
    assert desplegar(arbolito()) == ["raiz", "a", "a1", "a2", "b"]


def test_buscar_nodo():
    assert buscar_nodo(arbolito(), "a2")["nombre"] == "a2"
    assert buscar_nodo(arbolito(), "no-existe") is None


def test_contar_hojas():
    assert contar_hojas(arbolito()) == 3
    assert contar_hojas(nodo("solo")) == 1


def test_ruta_hasta():
    assert ruta_hasta(arbolito(), "a1") == ["raiz", "a", "a1"]
    assert ruta_hasta(arbolito(), "nada") == []
